from itertools import permutations

def check_m_distinct(m):
    # For a set of distinct residues {0, 1, ..., m-1}
    res = list(range(m))
    s1 = sum(res)
    if s1 % m == 0:
        return True

    # Check if there's a permutation sigma such that sum i * x_sigma(i) = 0 (mod m)
    # The positions are 1, 2, ..., m.
    for p in permutations(res):
        s2 = 0
        for i in range(1, m + 1):
            s2 += i * p[i-1]
        if s2 % m == 0:
            return True
    return False

for m in range(2, 15):
