def check_m_distinct_v2(m):
    res = list(range(m))
    s1 = sum(res)
    if s1 % m == 0:
        return True

    # Try to find a permutation
    import itertools
    for p in itertools.permutations(res):
        s2 = sum(i * p[i-1] for i in range(1, m + 1))
        if s2 % m == 0:
            return True
    return False

